#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    char *filename = "file.txt";
    char buffer[1024];
    FILE *fp;

    // Open the file for reading
    fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return 1;
    }

    // Read the entire file into a buffer
    while (!feof(fp)) {
        fgets(buffer, sizeof(buffer), fp);
        printf("%s", buffer);
    }

    // Close the file
    fclose(fp);

    return 0;
}
