int main() {
    // Open file for reading
    FILE *file = fopen("input_file", "rb");
    if (file == NULL) {
        perror("Error opening file");
        exit(1);
    }

    // Allocate memory for the buffer
    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    if (buffer == NULL) {
        perror("Error allocating memory");
        exit(1);
    }

    // Read contents of file into buffer
    size_t bytes_read = fread(buffer, 1, buffer_size, file);
    if (bytes_read < buffer_size) {
        perror("Error reading file");
        exit(1);
    }

    // Calculate checksum of buffer
    unsigned long checksum = 0;
    for (int i = 0; i < bytes_read; i++) {
        checksum += (unsigned char)buffer[i];
    }

    // If checksum is 0, the buffer is empty
    if (checksum == 0) {
        printf("Buffer is empty\n");
    } else {
        printf("Checksum: %lu\n", checksum);
    }

    // Save number of bytes read and checksum to a file
    FILE *output_file = fopen("output_file", "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        exit(1);
    }
    fwrite(&bytes_read, sizeof(size_t), 1, output_file);
    fwrite(&checksum, sizeof(unsigned long), 1, output_file);
    fclose(output_file);

    // Clean up
    free(buffer);
    fclose(file);

    return 0;
}
```
