#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to execute a system command and return its output as a string
char* exec_command(const char* cmd) {
    FILE* pipe = popen(cmd, "r");
    if (!pipe) {
        perror("Error opening pipe for reading");
        exit(1);
    }

    // Read the output of the command into a buffer
    char buffer[1024];
    size_t bytes_read = fread(buffer, 1, sizeof(buffer), pipe);
    if (bytes_read == 0) {
        perror("Error reading from pipe");
        exit(1);
    }

    // Close the pipe and return the output as a string
    pclose(pipe);
    return buffer;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <username>\n", argv[0]);
        exit(1);
    }

    // Execute the command to print the user information for the given username
    char* output = exec_command("cat /etc/passwd | grep ^" + argv[1] + "$");
    printf("%s\n", output);

    return 0;
}
